def rects(g,bg):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=bg and not seen[i][j]:
                c=g[i][j]; st=[(i,j)]; cells=[]
                while st:
                    y,x=st.pop()
                    if 0<=y<h and 0<=x<w and g[y][x]==c and not seen[y][x]:
                        seen[y][x]=True; cells.append((y,x))
                        st.extend([(y+1,x),(y-1,x),(y+1,x-1),(y+1,x+1),(y,x-1),(y,x+1)])
                ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
                out.append((c,min(ys),min(xs),max(ys),max(xs)))
    return out

def pat(c,h,w):
    o=[[0]*w for _ in range(h)]
    corners=[(0,0),(0,w-1),(h-1,0),(h-1,w-1)]
    for y in range(h):
        for x in range(w):
            if (y,x) in corners: o[y][x]=1
            elif y in (0,h-1) or x in (0,w-1): o[y][x]=4
            else: o[y][x]=2
    return o

def solve(g,bg=None):
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    rs=rects(g,bg)
    o=[[bg]*len(g[0]) for _ in g]
    for c,y0,x0,y1,x1 in rs:
        p=pat(c,y1-y0+1,x1-x0+1)
        for y in range(y0,y1+1):
            for x in range(x0,x1+1):
                o[y][x]=p[y-y0][x-x0]
    return o

